-- NovaMart practice database: fictional data created by GradOpus Labs for the Data Analytics program.
-- Running this script deletes and recreates the database called novamart.
DROP DATABASE IF EXISTS novamart;
CREATE DATABASE novamart;
USE novamart;

CREATE TABLE customers (
  customer_id VARCHAR(10) PRIMARY KEY,
  customer_name VARCHAR(100) NOT NULL,
  city VARCHAR(50) NOT NULL,
  state VARCHAR(50) NOT NULL,
  signup_date DATE NOT NULL,
  acquisition_channel VARCHAR(30) NOT NULL
);

CREATE TABLE products (
  product_id VARCHAR(10) PRIMARY KEY,
  product_name VARCHAR(100) NOT NULL,
  category VARCHAR(50) NOT NULL,
  unit_price DECIMAL(10, 2) NOT NULL,
  unit_cost DECIMAL(10, 2) NOT NULL
);

CREATE TABLE orders (
  order_id VARCHAR(12) PRIMARY KEY,
  customer_id VARCHAR(10) NOT NULL,
  order_date DATE NOT NULL,
  payment_method VARCHAR(30) NOT NULL,
  order_status VARCHAR(20) NOT NULL,
  FOREIGN KEY (customer_id) REFERENCES customers (customer_id)
);

CREATE TABLE order_items (
  order_item_id INT PRIMARY KEY,
  order_id VARCHAR(12) NOT NULL,
  product_id VARCHAR(10) NOT NULL,
  quantity INT NOT NULL,
  unit_price DECIMAL(10, 2) NOT NULL,
  discount_pct DECIMAL(5, 2) NOT NULL,
  FOREIGN KEY (order_id) REFERENCES orders (order_id),
  FOREIGN KEY (product_id) REFERENCES products (product_id)
);





SELECT 'NovaMart database created' AS status;
